// Single source of the OnePick UI icon geometry. Every icon is drawn in a 24×24
// box with a 1.8 round stroke so it can be shown at icon/size/md (24) or
// icon/size/sm (16) without redrawing. The Figma Foundations "OnePick / Icon"
// components and `public/icons/ui/*.svg` (generated by scripts/generate-ui-icons.cjs)
// use exactly these shapes, so app and Figma stay in parity.

export type IconShape =
  | { type: 'path'; d: string }
  | { type: 'circle'; cx: number; cy: number; r: number; filled?: boolean }
  | { type: 'rect'; x: number; y: number; w: number; h: number; rx: number };

export const ICON_VIEWBOX = 24;

